// Classify and extract amount from email
const items = $input.all();
const results = [];

const POSITIVE_PATTERNS = [
  [/(?:receipt| invoice|order\s*(confirmation|summary)|payment\s*(received|processed|confirmed)|thank you for your purchase|you.?ve been charged|amount\s*paid|order\s*confirmed|charged.*\d)/i, 'Receipt'],
  [/invoice/i, 'Invoice'],
  [/(?:transaction\s*confirmation|payment\s*for)/i, 'Transaction Confirmation']
];

const NEGATIVE_PATTERNS = [
  /gift\s*(her|him|card)/i,
  /savings?\s*(for\s*you|big)/i,
  /celebrate.*with\s*popcorn/i,
  /rewards?\s*(members?)?\s*get/i,
  /payment\s*(was\s*)?unsuccessful/i,
  /wasn.?t\s*able\s*to\s*charge/i,
  /interac.*received/i,
  /ve\s*been\s*automatically\s*deposited/i,
  /affirm/i,
  /star\s*wars/i,
  /cineplex/i,
  /westjet/i,
  /big\s*city\s*plans/i,
  /you.?ve\s*received.*from/i,
  /funds.*deposited/i
];

function extractAmount(text) {
  const totalPatterns = [
    /(?:^|[,\s])[Tt]otal[:\s]*\$?[\d,]+\.\d{2}/,
    /you.?ve\s*been\s*charged\s*\$?[\d,]+\.\d{2}/,
    /charged\s*\$?[\d,]+\.\d{2}/,
    /Amount\s*(?:paid|charged)?[:\s]*\$?[\d,]+\.\d{2}/
  ];
  for (const p of totalPatterns) {
    const m = text.match(p);
    if (m) {
      const amt = (m[0].match(/\$?[\d,]+\.\d{2}/) || [])[0];
      if (amt) return amt.startsWith('$') ? amt : '$' + amt;
    }
  }
  const amounts = text.match(/\$[\d,]+\.\d{2}/g) || [];
  if (amounts.length) {
    return amounts.sort((a, b) => parseFloat(b.replace(/[$,]/g,'')) - parseFloat(a.replace(/[$,]/g,'')))[0];
  }
  return '';
}

function classify(subject, body) {
  const text = (subject + ' ' + body).toLowerCase();
  for (const p of NEGATIVE_PATTERNS) {
    if (p.test(text)) return 'Other';
  }
  for (const [pat, cat] of POSITIVE_PATTERNS) {
    if (pat.test(text)) return cat;
  }
  return 'Other';
}

for (const item of items) {
  const msg = item.json;
  const body = msg.bodyText || msg.snippet || '';
  const amount = extractAmount(body);
  const category = classify(msg.subject || '', body);
  results.push({
    json: {
      id: msg.id,
      subject: msg.subject,
      sender: msg.from,
      date: msg.date,
      snippet: msg.snippet,
      amount,
      category,
      link: `https://mail.google.com/mail/u/0/#inbox/${msg.id}`
    }
  });
}

return results;

// Filter: skip no-amount, Other (not tax-related), and duplicates
const inputItems = $input.all();
const existingIds = $('Get Existing Entries').all().map(i => i.json.id).filter(Boolean);
const results = [];


for (const item of inputItems) {
  const data = item.json;

  if (existingIds.includes(data.id)) {
    continue; // duplicate - skip
  }
  if (!data.amount) {
    continue; // no amount
  }
  if (data.category === 'Other') {
    continue; // not tax-related
  }
  results.push({ json: data });
}

return results;
